let n = 0, diff = 0, diffNonZero = 0, zero = 0, bulk = 0;
for (let i = 0; i < 200000; i++) {
  const lines = rnd(16);
  const items = Array.from({ length: lines }, () => ({ price: rnd(100001), qty: rnd(21) }));
  if (items.reduce((a, x) => a + x.price * x.qty, 0) === 0) zero++;
  if (lines >= 10) bulk++;
  for (const args of [[items], [items, 0]]) {
    n++;
    if (oldTotal(...args) !== newTotal(...args)) { diff++; if (diff <= 3) console.log('DIFF', JSON.stringify(args)); }
  }
  if (lines > 0 && oldTotal(items, 0.1) !== newTotal(items, 0.1)) diffNonZero++;
